\begin{tikzpicture}[font=\sffamily, scale=1.2]
    % Plant cell (rectangular with rounded corners)
    \draw[thick] (0,0) rectangle (5,3.5);

    % Cell wall thickness (inner line for plasma membrane / cytoplasm boundary)
    \draw[thin] (0.15,0.15) rectangle (4.85,3.35);

    % Large central vacuole
    \draw[thick] (1.2,0.8) rectangle (3.8,2.7);

    % Nucleus (with small nucleolus)
    \draw[thick] (4.0,1.7) ellipse (0.4 and 0.5);
    \fill (4.1,1.7) circle (0.08);

    % Chloroplasts (oval shapes with a few internal lines or just shaded ovals)
    \draw[thick] (0.8,2.8) ellipse (0.3 and 0.15);
    \draw[thick] (2.5,3.0) ellipse (0.25 and 0.12);
    \draw[thick] (4.5,0.8) ellipse (0.15 and 0.3);
    \draw[thick] (0.6,0.5) ellipse (0.25 and 0.15);

    % Cytoplasm is the space between vacuole, nucleus, and inner boundary.

    % Pointer lines and labels (A to E)
    % A: Cell wall (outer line)
    \draw[thick] (0, 3.5) -- (-0.8, 3.8) node[left] {A};

    % B: Cytoplasm
    \draw[thick] (0.5, 0.15) -- (-0.8, 0.5) node[left] {B};

    % C: Vacuole
    \draw[thick] (2.5, 1.75) -- (2.5, 4.2) node[above] {C};

    % D: Chloroplast
    \draw[thick] (0.8, 2.8) -- (-0.8, 2.2) node[left] {D};

    % E: Nucleus
    \draw[thick] (4.0, 1.7) -- (5.8, 1.7) node[right] {E};

    % Caption
    \node at (2.5, -0.6) {Fig. 1.1};
\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.3]
    % Outer cell wall (rounded rectangle)
    \draw[thick, rounded corners=6pt] (0,0) rectangle (6,4);

    % Inner plasma membrane (slightly inside cell wall)
    \draw[thick, rounded corners=4pt] (0.2,0.2) rectangle (5.8,3.8);

    % Large central vacuole (smooth, slightly irregular shape filling the center)
    \draw[thick, rounded corners=8pt] (1.5,0.8) rectangle (4.5,3.2);

    % Nucleus (drawn near the side, with double membrane appearance)
    \draw[thick] (4.8, 1.8) ellipse (0.7 and 0.55);
    % Nucleolus inside nucleus
    \fill (4.8, 1.8) circle (0.12);

    % Chloroplasts (several bean-shaped structures scattered in cytoplasm)
    \draw[thick, rotate=15] (1.0, 3.0) ellipse (0.35 and 0.2);
    \draw[thick, rotate=-20] (5.0, 0.9) ellipse (0.35 and 0.2);
    \draw[thick, rotate=45] (1.2, 1.0) ellipse (0.35 and 0.2);
    \draw[thick, rotate=-10] (3.0, 3.5) ellipse (0.35 and 0.2);

    % Pointer lines and labels (A to E)
    % A: Cell wall
    \node[left] at (-0.8, 3.6) {A};
    \draw[thick] (-0.7, 3.6) -- (0.1, 3.6);

    % B: Cytoplasm (pointing to the region between vacuole and plasma membrane)
    \node[left] at (-0.8, 0.4) {B};
    \draw[thick] (-0.7, 0.4) -- (0.5, 0.4);

    % C: Vacuole (pointing to the large central vacuole space)
    \node[above] at (3.0, 4.5) {C};
    \draw[thick] (3.0, 4.4) -- (3.0, 2.5);

    % D: Chloroplast
    \node[left] at (-0.8, 2.2) {D};
    \draw[thick] (-0.7, 2.2) -- (0.8, 2.2);

    % E: Nucleus
    \node[right] at (6.8, 1.8) {E};
    \draw[thick] (6.7, 1.8) -- (5.5, 1.8);

    % Fig. caption
    \node at (3.0, -0.6) {Fig. 1.1};
\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.3]
    % Outer cell wall (rounded rectangle)
    \draw[thick, rounded corners=6pt] (0,0) rectangle (6,4);

    % Inner plasma membrane (slightly inside cell wall)
    \draw[thin, rounded corners=4pt] (0.2,0.2) rectangle (5.8,3.8);

    % Large central vacuole (smooth, filling the center without overlapping nucleus)
    \draw[thick, rounded corners=8pt] (1.0,0.8) rectangle (3.8,3.2);

    % Nucleus (drawn clearly in the cytoplasm, to the right of the vacuole)
    \draw[thick] (4.8, 2.0) ellipse (0.6 and 0.5);
    % Nucleolus inside nucleus
    \fill (4.8, 2.0) circle (0.09);

    % Chloroplasts (bean-shaped structures scattered in cytoplasm, fully inside)
    \draw[thick, rotate=15] (1.5, 3.4) ellipse (0.3 and 0.15);
    \draw[thick, rotate=-20] (4.8, 0.8) ellipse (0.3 and 0.15);
    \draw[thick, rotate=30] (2.4, 0.45) ellipse (0.3 and 0.15);

    % Pointer lines and labels (A to E)
    % A: Cell wall
    \node[left] at (-0.8, 3.6) {A};
    \draw[thick] (-0.7, 3.6) -- (0.1, 3.6);

    % B: Cytoplasm
    \node[left] at (-0.8, 0.5) {B};
    \draw[thick] (-0.7, 0.5) -- (0.5, 0.5);

    % C: Vacuole
    \node[above] at (2.4, 4.4) {C};
    \draw[thick] (2.4, 4.3) -- (2.4, 2.0);

    % D: Chloroplast
    \node[left] at (-0.8, 2.0) {D};
    \draw[thick] (-0.7, 2.0) -- (1.5, 2.3);

    % E: Nucleus
    \node[right] at (6.8, 2.0) {E};
    \draw[thick] (6.7, 2.0) -- (5.4, 2.0);

    % Fig. caption
    \node at (3.0, -0.6) {Fig. 1.1};
\end{tikzpicture}
